sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    try {
        var custMaster = current;
        if (!custMaster || !custMaster.isValidRecord()) {
            template.print("<div style='font-family: Arial, sans-serif; color: #d9534f;'>Customer record unavailable</div>");
            return;
        }

        function esc(str) {
            if (str === null || str === undefined) return '';
            return (str + '')
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        }

        var meta = {};
        try {
            meta = JSON.parse(event.parm2 || '{}');
        } catch (e) {
            meta = {};
        }

        var custName = custMaster.getValue('customer_name') || meta.companyName || 'Non-Trade Customer';
        var pan = custMaster.getValue('pan') || meta.maskedPan || '—';
        var siteCount = meta.siteCount || 1;

        // Resolve TSH name from link_sent_by reference, event payload, or user lookup
        var recipientName = meta.repName || 'Team';
        if (custMaster.link_sent_by) {
            var sentByGr = custMaster.link_sent_by.getRefRecord();
            if (sentByGr && sentByGr.isValidRecord()) {
                recipientName = sentByGr.getValue('name') || recipientName;
            }
        } else if (event && event.parm1) {
            var uGr = new GlideRecord('sys_user');
            if (uGr.get('email', event.parm1 + '')) {
                recipientName = uGr.getValue('name') || recipientName;
            }
        }

        email.setSubject('Non-Trade Documents Submitted: ' + custName + ' (' + pan + ')');

        var submitTime = new GlideDateTime().getDisplayValue();
        var baseUrl = gs.getProperty('glide.servlet.uri') || 'https://abgdev.service-now.com/';
        var cleanBase = baseUrl.replace(/\/$/, "");
        var dashboardUrl = cleanBase + '/uclm?id=uclm_nt_document_submission';

        var h = '';
        h += '<p style="margin: 0 0 16px 0; font-size: 15px; line-height: 1.5; color: #1a1a1a;">Dear <strong>' + esc(recipientName) + '</strong>,</p>';
        h += '<p style="margin: 0 0 20px 0; font-size: 14px; line-height: 1.6; color: #3a4451;">';
        h += 'The Non-Trade customer below has successfully completed their operational figures submission and uploaded supporting documents across all mapped operating child sites via the secure portal.';
        h += '</p>';

        // Summary Card
        h += '<div style="margin-bottom: 24px; border: 1px solid #e0e6ed; border-radius: 6px; background-color: #fafbfc; overflow: hidden;">';
        h += '  <div style="padding: 10px 16px; background-color: #f1f3f7; border-bottom: 1px solid #dde3ea; font-size: 12px; font-weight: bold; text-transform: uppercase; letter-spacing: 0.8px; color: #1a1a1a;">';
        h += '    Submission Summary';
        h += '  </div>';
        h += '  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="font-size: 13.5px; border-collapse: collapse;">';
        h += '    <tr>';
        h += '      <td width="36%" style="padding: 10px 16px; color: #5a6a7a; border-bottom: 1px solid #edf1f5;">Company Name</td>';
        h += '      <td style="padding: 10px 16px; color: #1a1a1a; font-weight: 700; border-bottom: 1px solid #edf1f5;">' + esc(custName) + '</td>';
        h += '    </tr>';
        h += '    <tr>';
        h += '      <td style="padding: 10px 16px; color: #5a6a7a; border-bottom: 1px solid #edf1f5;">Corporate PAN</td>';
        h += '      <td style="padding: 10px 16px; color: #1a1a1a; font-weight: 700; font-family: monospace; border-bottom: 1px solid #edf1f5;">' + esc(pan) + '</td>';
        h += '    </tr>';
        h += '    <tr>';
        h += '      <td style="padding: 10px 16px; color: #5a6a7a; border-bottom: 1px solid #edf1f5;">Mapped Child Sites</td>';
        h += '      <td style="padding: 10px 16px; color: #1a1a1a; font-weight: 700; border-bottom: 1px solid #edf1f5;">' + siteCount + ' Site' + (siteCount > 1 ? 's' : '') + ' Included</td>';
        h += '    </tr>';
        h += '    <tr>';
        h += '      <td style="padding: 10px 16px; color: #5a6a7a;">Submitted On</td>';
        h += '      <td style="padding: 10px 16px; color: #1e8449; font-weight: 700;">' + esc(submitTime) + '</td>';
        h += '    </tr>';
        h += '  </table>';
        h += '</div>';

        // Direct Dashboard Button
        h += '<table role="presentation" border="0" cellspacing="0" cellpadding="0" style="margin-bottom: 24px;"><tbody><tr>';
        h += '  <td align="center" bgcolor="#E87722" style="border-radius: 6px;">';
        h += '    <a href="' + dashboardUrl + '" target="_blank" rel="noopener" style="display: inline-block; padding: 13px 32px; font-family: \'Segoe UI\', Arial, sans-serif; font-size: 14px; font-weight: bold; color: #ffffff; text-decoration: none; border-radius: 6px; letter-spacing: 0.5px;">';
        h += '      View Submitted Data in CredX &rarr;';
        h += '    </a>';
        h += '  </td>';
        h += '</tr></tbody></table>';

        h += '<div style="margin-bottom: 20px; padding: 12px 14px; background-color: #f4f5f7; border: 1px dashed #cdd4dc; border-radius: 6px; font-size: 12px; color: #5a6a7a;">';
        h += '  <div style="margin-bottom: 4px; font-weight: bold; color: #3a4451;">Direct Link:</div>';
        h += '  <a href="' + dashboardUrl + '" target="_blank" style="color: #AF272F; word-break: break-all; text-decoration: underline;">' + dashboardUrl + '</a>';
        h += '</div>';

        template.print(h);

    } catch (err) {
        gs.error('[clm_submission_rep_script] Exception: ' + err.message);
        template.print('<div style="color:red; font-size:12px;">Error generating submission notice: ' + esc(err.message) + '</div>');
    }
})(current, template, email, email_action, event);
